import React from 'react';
import { ChatProvider, useChat } from './context/ChatContext';
import { Header } from './components/Header';
import { SideDrawer } from './components/SideDrawer';
import { BottomNav } from './components/BottomNav';
import { StudioLobby } from './components/StudioLobby';
import { ActiveCoaching } from './components/ActiveCoaching';
import { RepertoireView } from './components/RepertoireView';
import { ArtistProfileView } from './components/ArtistProfileView';

const MainContent: React.FC = () => {
  const { activeTab, toastMessage } = useChat();

  return (
    <div className="bg-[#FAF9F5] text-[#1B1C1A] font-body-md text-body-md flex flex-col min-h-screen relative selection:bg-[#FFDCBF] selection:text-[#2D1600]">
      {/* Toast Notification */}
      {toastMessage && (
        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-50 pointer-events-none transition-all duration-300">
          <div className="px-4 py-2 bg-[#1B1C1A] text-white text-xs font-medium rounded-full shadow-lg border border-[#3E3E3E] flex items-center gap-2">
            <span>{toastMessage}</span>
          </div>
        </div>
      )}

      {/* Top Fixed Header */}
      <Header />

      {/* Slide-out Sidebar Drawer */}
      <SideDrawer />

      {/* Main View Port */}
      <main className="flex-1 flex flex-col relative w-full">
        {activeTab === 'studio' && <StudioLobby />}
        {activeTab === 'coach' && <ActiveCoaching />}
        {activeTab === 'repertoire' && <RepertoireView />}
        {activeTab === 'artist' && <ArtistProfileView />}
      </main>

      {/* Bottom Pinned Navigation Bar */}
      <BottomNav />
    </div>
  );
};

export default function App() {
  return (
    <ChatProvider>
      <MainContent />
    </ChatProvider>
  );
}
