import React, { useState, useRef, useEffect } from 'react';
import { useChat } from '../context/ChatContext';
import { MarkdownRenderer } from './MarkdownRenderer';
import { InteractivePracticeBar } from './InteractivePracticeBar';

export const ActiveCoaching: React.FC = () => {
  const {
    currentConversation,
    sendMessage,
    isGenerating,
    streamingText,
    stopGeneration,
    saveToRepertoire,
    showToast,
    error,
    clearError,
    artistProfile,
  } = useChat();

  const [inputVal, setInputVal] = useState('');
  const [isListening, setIsListening] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [currentConversation?.messages, streamingText]);

  const handleSend = (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if (!inputVal.trim() || isGenerating) return;
    const text = inputVal.trim();
    setInputVal('');
    sendMessage(text);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleSend();
    }
  };

  const handleChipClick = (promptText: string) => {
    setInputVal(promptText);
    inputRef.current?.focus();
  };

  const handleCopy = (text: string) => {
    if (navigator.clipboard) {
      navigator.clipboard.writeText(text);
      showToast('Copied rehearsal breakdown to clipboard 📋');
    }
  };

  const handleSaveRepertoire = (title: string, notes: string) => {
    saveToRepertoire({
      title: title || currentConversation?.title || 'Rehearsal Notes',
      discipline: currentConversation?.discipline || 'General',
      excerpt: notes.slice(0, 120) + '...',
      fullNotes: notes,
      targetBpm: 108,
    });
  };

  const handleExport = (text: string) => {
    const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Grooveyy-${(currentConversation?.title || 'Rehearsal').replace(/\s+/g, '-')}.txt`;
    a.click();
    URL.revokeObjectURL(url);
    showToast('Exported rehearsal notes 📄');
  };

  // Voice Rehearsal Dictation with SpeechRecognition
  const handleToggleVoice = () => {
    const SpeechRecognition =
      (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;

    if (!SpeechRecognition) {
      showToast('Speech recognition is not supported in this browser environment.');
      return;
    }

    if (isListening) {
      setIsListening(false);
      return;
    }

    try {
      const recognition = new SpeechRecognition();
      recognition.lang = 'en-US';
      recognition.continuous = false;
      recognition.interimResults = false;

      setIsListening(true);
      showToast('Listening... Speak your cue 🎙️');

      recognition.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInputVal((prev) => (prev ? `${prev} ${transcript}` : transcript));
        setIsListening(false);
        showToast(`Dictated: "${transcript.slice(0, 30)}..."`);
      };

      recognition.onerror = () => {
        setIsListening(false);
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognition.start();
    } catch {
      setIsListening(false);
    }
  };

  const messages = currentConversation?.messages || [];
  const contextTag =
    currentConversation?.contextTag ||
    `${currentConversation?.discipline || 'Stage'} • Live Coaching Lab`;

  return (
    <div className="flex-1 flex flex-col relative w-full pt-16 pb-20 bg-[#FAF9F5]">
      {/* Floating Sticky Context Capsule */}
      <div className="sticky top-16 z-30 px-4 py-2 flex justify-center backdrop-blur-md bg-[#FAF9F5]/90 border-b border-[#E8E6DF]/40">
        <div className="flex items-center gap-2 bg-[#E9E8E4]/90 text-[#534437] px-3.5 py-1.5 rounded-full shadow-xs max-w-full">
          <span className="w-2 h-2 rounded-full bg-[#884E00] animate-pulse flex-shrink-0" />
          <span className="font-label-sm text-[11px] font-semibold tracking-wide uppercase text-[#884E00] truncate">
            Audition Prep
          </span>
          <span className="text-[#867465] text-xs">•</span>
          <span className="font-label-sm text-[11px] truncate">{contextTag}</span>
          <span className="material-symbols-outlined text-[#867465] text-[16px] flex-shrink-0 ml-0.5">
            music_note
          </span>
        </div>
      </div>

      {/* Error Banner */}
      {error && (
        <div className="max-w-xl mx-auto w-full px-4 pt-2">
          <div className="p-3 bg-[#FFDAD6] border border-[#BA1A1A]/30 rounded-xl flex items-center justify-between text-xs text-[#93000A]">
            <div className="flex items-center gap-2">
              <span className="material-symbols-outlined text-[18px]">error</span>
              <span>{error}</span>
            </div>
            <button
              type="button"
              onClick={clearError}
              className="text-[#93000A] font-bold text-xs p-1 cursor-pointer"
            >
              ✕
            </button>
          </div>
        </div>
      )}

      {/* Rehearsal Stage Conversation Container */}
      <div className="px-4 pt-3 pb-28 space-y-6 max-w-xl mx-auto w-full flex-1">
        {/* Timestamp Marker */}
        <div className="flex justify-center">
          <span className="font-label-sm text-[11px] text-[#867465] px-3 py-1 bg-[#F4F4F0] rounded-full border border-[#E8E6DF]/50">
            Today, 2:42 PM • Callback Session (3 Days Out)
          </span>
        </div>

        {/* Empty State if fresh conversation */}
        {messages.length === 0 && !isGenerating && (
          <div className="py-12 px-4 text-center space-y-4">
            <div className="w-16 h-16 rounded-full bg-[#FFDCBF]/60 p-2 mx-auto flex items-center justify-center border border-[#FFDCBF]">
              <img
                src="/grooveyy-mascot.png"
                alt="Grooveyy"
                className="w-full h-full object-cover rounded-full"
              />
            </div>
            <h3 className="font-headline-sm text-base font-bold text-[#1B1C1A]">
              Your Stage is Ready for Rehearsal
            </h3>
            <p className="font-body-sm text-xs text-[#534437] max-w-sm mx-auto leading-relaxed">
              Ask Grooveyy for vocal mechanics, choreography sequences, script analysis, or audition cues.
            </p>
            <div className="flex flex-wrap justify-center gap-2 pt-2">
              {[
                'How do I steady my breathing during quick patter lines?',
                'Give me a 5-step warmup before my musical callback',
                'Break down character objective vs tactical action',
              ].map((starter, i) => (
                <button
                  key={i}
                  type="button"
                  onClick={() => sendMessage(starter)}
                  className="px-3 py-1.5 rounded-full bg-white text-[#534437] border border-[#E8E6DF] text-xs hover:border-[#884E00] hover:text-[#884E00] transition-all cursor-pointer shadow-xs active:scale-95"
                >
                  {starter}
                </button>
              ))}
            </div>
          </div>
        )}

        {/* Message Turns */}
        {messages.map((msg, index) => {
          if (msg.role === 'user') {
            return (
              <div key={msg.id} className="flex flex-col items-end pl-6">
                <div className="bg-[#EFEEEA] rounded-2xl rounded-tr-xs p-4 shadow-xs space-y-1.5 max-w-[94%] border border-[#E3E2DF]/60">
                  <div className="flex items-center gap-1.5 text-[#884E00] text-xs font-semibold">
                    <span className="material-symbols-outlined text-[15px]">record_voice_over</span>
                    <span className="font-label-sm text-[11px]">
                      {msg.userRoleTitle || artistProfile.roleTitle || 'Audition Candidate'}
                    </span>
                  </div>
                  <p className="font-body-md text-sm text-[#1B1C1A] leading-relaxed whitespace-pre-wrap">
                    {msg.content}
                  </p>
                </div>
                <span className="font-label-sm text-[11px] text-[#867465] mt-1 mr-1">
                  Delivered
                </span>
              </div>
            );
          }

          // Model turn
          const isInitialSondheimTurn = msg.isInitialMock && index === 1;

          return (
            <div key={msg.id} className="flex items-start gap-3 w-full">
              {/* Mascot Badge */}
              <div className="flex-shrink-0 relative">
                <div className="w-9 h-9 rounded-full bg-[#FFDCBF] p-0.5 shadow-xs overflow-hidden flex items-center justify-center border border-[#FFDCBF]">
                  <img
                    src="/grooveyy-mascot.png"
                    alt="Grooveyy Studio Coach"
                    className="w-full h-full object-cover rounded-full select-none"
                  />
                </div>
                <span className="absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 rounded-full bg-white flex items-center justify-center shadow-xs">
                  <span className="w-2 h-2 rounded-full bg-[#884E00]" />
                </span>
              </div>

              {/* Coach Response Body */}
              <div className="flex-1 min-w-0 space-y-4">
                {/* Header Tag */}
                <div className="flex items-center gap-2">
                  <span className="font-headline-sm text-sm font-bold text-[#1B1C1A]">
                    Grooveyy Performing Arts Coach
                  </span>
                  <span className="px-2 py-0.5 rounded-full bg-[#DAE2FF] text-[#001847] font-label-sm text-[11px] font-medium">
                    {msg.disciplineTag || 'Active Coaching'}
                  </span>
                </div>

                {/* Render Markdown Content */}
                <div className="text-sm">
                  <MarkdownRenderer content={msg.content} />
                </div>

                {/* Interactive Practice Bar Widget */}
                {/* Embed for patter/tempo/singing coaching or initial mock */}
                {(isInitialSondheimTurn ||
                  msg.content.toLowerCase().includes('metronome') ||
                  msg.content.toLowerCase().includes('bpm') ||
                  msg.content.toLowerCase().includes('patter') ||
                  msg.content.toLowerCase().includes('tempo')) && (
                  <InteractivePracticeBar
                    initialBpm={108}
                    label="Rehearsal mm. 14–32 • Patter Lab"
                  />
                )}

                {/* Practical Action Bar */}
                <div className="flex items-center justify-between pt-2 border-t border-[#E8E6DF]/60">
                  <div className="flex items-center gap-1 text-[#867465]">
                    <button
                      type="button"
                      onClick={() => handleCopy(msg.content)}
                      className="p-2 rounded-full hover:bg-[#EFEEEA] text-[#534437] transition-colors cursor-pointer"
                      title="Copy breakdown"
                    >
                      <span className="material-symbols-outlined text-[19px]">content_copy</span>
                    </button>
                    <button
                      type="button"
                      onClick={() =>
                        handleSaveRepertoire(
                          `Drill: ${currentConversation?.title || 'Session'}`,
                          msg.content
                        )
                      }
                      className="p-2 rounded-full hover:bg-[#EFEEEA] text-[#534437] transition-colors cursor-pointer"
                      title="Save to Repertoire"
                    >
                      <span className="material-symbols-outlined text-[19px]">bookmark_add</span>
                    </button>
                    <button
                      type="button"
                      onClick={() => handleExport(msg.content)}
                      className="p-2 rounded-full hover:bg-[#EFEEEA] text-[#534437] transition-colors cursor-pointer"
                      title="Export Audition Sheet Notes"
                    >
                      <span className="material-symbols-outlined text-[19px]">ios_share</span>
                    </button>
                  </div>

                  <span className="font-label-sm text-[11px] text-[#867465] flex items-center gap-1">
                    <span className="material-symbols-outlined text-[15px] text-[#884E00]">
                      verified
                    </span>
                    Audition Ready Coach
                  </span>
                </div>

                {/* Suggested Follow-up Chips for this turn */}
                {isInitialSondheimTurn && (
                  <div className="pt-2 space-y-1.5">
                    <span className="font-label-sm text-[11px] text-[#867465] uppercase tracking-wider block font-semibold">
                      Coaching Next Steps
                    </span>
                    <div className="flex flex-wrap gap-2">
                      <button
                        type="button"
                        onClick={() => handleChipClick('Drill tongue-twister measures 22–26 at 96 BPM')}
                        className="chip flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-white shadow-xs text-[#534437] hover:text-[#884E00] border border-[#E8E6DF] transition-all active:scale-95 text-left text-xs cursor-pointer"
                      >
                        <span className="material-symbols-outlined text-[#884E00] text-[16px]">
                          repeat
                        </span>
                        <span className="font-label-md">Drill tongue-twister measures 22–26</span>
                      </button>
                      <button
                        type="button"
                        onClick={() =>
                          handleChipClick('Adjust for Baritone key (-1 tone) and show breath marks')
                        }
                        className="chip flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-white shadow-xs text-[#534437] hover:text-[#884E00] border border-[#E8E6DF] transition-all active:scale-95 text-left text-xs cursor-pointer"
                      >
                        <span className="material-symbols-outlined text-[#305AB4] text-[16px]">
                          piano
                        </span>
                        <span className="font-label-md">Adjust for Baritone key (-1 tone)</span>
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          );
        })}

        {/* Live Streaming Response State */}
        {isGenerating && (
          <div className="flex items-start gap-3 w-full animate-fade-in">
            <div className="flex-shrink-0 relative">
              <div className="w-9 h-9 rounded-full bg-[#FFDCBF] p-0.5 shadow-xs overflow-hidden flex items-center justify-center border border-[#FFDCBF]">
                <img
                  src="/grooveyy-mascot.png"
                  alt="Grooveyy"
                  className="w-full h-full object-cover rounded-full animate-pulse"
                />
              </div>
              <span className="absolute -bottom-0.5 -right-0.5 w-3.5 h-3.5 rounded-full bg-white flex items-center justify-center shadow-xs">
                <span className="w-2 h-2 rounded-full bg-[#884E00] animate-ping" />
              </span>
            </div>

            <div className="flex-1 min-w-0 space-y-2">
              <div className="flex items-center justify-between">
                <span className="font-headline-sm text-xs font-bold text-[#884E00] flex items-center gap-1.5">
                  <span className="material-symbols-outlined text-[16px] animate-spin">
                    progress_activity
                  </span>
                  Grooveyy is preparing your coaching breakdown...
                </span>
                <button
                  type="button"
                  onClick={stopGeneration}
                  className="px-2 py-0.5 rounded text-[11px] font-semibold bg-[#FFDAD6] text-[#93000A] hover:bg-[#BA1A1A] hover:text-white transition-colors cursor-pointer"
                >
                  Stop
                </button>
              </div>

              {streamingText ? (
                <div className="text-sm">
                  <MarkdownRenderer content={streamingText} />
                </div>
              ) : (
                <div className="space-y-2 py-2">
                  <div className="h-3 bg-[#E9E8E4] rounded-full w-3/4 animate-pulse" />
                  <div className="h-3 bg-[#E9E8E4] rounded-full w-5/6 animate-pulse" />
                  <div className="h-3 bg-[#E9E8E4] rounded-full w-1/2 animate-pulse" />
                </div>
              )}
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Pinned Bottom Mobile Composer Dock */}
      <div className="fixed bottom-16 inset-x-0 z-30 px-4 py-2 backdrop-blur-xl bg-[#FAF9F5]/90 border-t border-[#E8E6DF]/60">
        <div className="max-w-xl mx-auto">
          <form
            onSubmit={handleSend}
            className="bg-white rounded-full p-1.5 shadow-[0_8px_30px_-4px_rgba(40,35,25,0.08)] border border-[#E8E6DF] flex items-center gap-2"
          >
            {/* Repertoire / Voice Attachment Button */}
            <button
              type="button"
              onClick={handleToggleVoice}
              className={`w-10 h-10 rounded-full flex items-center justify-center transition-colors cursor-pointer flex-shrink-0 ${
                isListening
                  ? 'bg-[#B51C12] text-white animate-pulse'
                  : 'text-[#867465] hover:text-[#884E00] hover:bg-[#EFEEEA]'
              }`}
              title="Speak or dictate rehearsal question"
            >
              <span className="material-symbols-outlined text-[20px]">mic</span>
            </button>

            {/* Dynamic Text Input */}
            <input
              ref={inputRef}
              type="text"
              value={inputVal}
              onChange={(e) => setInputVal(e.target.value)}
              onKeyDown={handleKeyDown}
              disabled={isGenerating}
              placeholder="Ask Grooveyy for vocal cues, cues, or rhythm drills..."
              className="flex-1 bg-transparent px-2 font-body-md text-sm text-[#1B1C1A] placeholder:text-[#867465] focus:outline-none"
            />

            {/* Send Pill Action */}
            <button
              type="submit"
              disabled={!inputVal.trim() || isGenerating}
              className={`w-10 h-10 rounded-full flex items-center justify-center shadow-xs transition-transform flex-shrink-0 cursor-pointer ${
                inputVal.trim() && !isGenerating
                  ? 'bg-[#884E00] text-white active:scale-90 hover:bg-[#6A3B00]'
                  : 'bg-[#E3E2DF] text-[#867465] cursor-not-allowed opacity-60'
              }`}
              title="Send Coaching Cue"
            >
              <span className="material-symbols-outlined text-[20px]">arrow_upward</span>
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};
