import React from 'react';

interface Props {
  content: string;
}

export const MarkdownRenderer: React.FC<Props> = ({ content }) => {
  // Parse paragraphs and special blocks cleanly
  const renderFormattedText = (text: string) => {
    // Process bold **text** and italic *text*
    const parts: React.ReactNode[] = [];
    let remaining = text;
    let keyIdx = 0;

    // Simple markdown inline parser
    while (remaining.length > 0) {
      const boldMatch = remaining.match(/\*\*(.*?)\*\*/);
      const italicMatch = remaining.match(/\*(.*?)\*/);

      let firstMatch: { match: RegExpMatchArray; type: 'bold' | 'italic' } | null = null;

      if (boldMatch && (!italicMatch || boldMatch.index! <= italicMatch.index!)) {
        firstMatch = { match: boldMatch, type: 'bold' };
      } else if (italicMatch) {
        firstMatch = { match: italicMatch, type: 'italic' };
      }

      if (firstMatch && firstMatch.match.index !== undefined) {
        const index = firstMatch.match.index;
        if (index > 0) {
          parts.push(remaining.substring(0, index));
        }
        if (firstMatch.type === 'bold') {
          parts.push(
            <strong key={keyIdx++} className="font-semibold text-[#1B1C1A]">
              {firstMatch.match[1]}
            </strong>
          );
        } else {
          parts.push(
            <em key={keyIdx++} className="italic text-[#534437]">
              {firstMatch.match[1]}
            </em>
          );
        }
        remaining = remaining.substring(index + firstMatch.match[0].length);
      } else {
        parts.push(remaining);
        break;
      }
    }

    return parts;
  };

  const lines = content.split('\n');
  const elements: React.ReactNode[] = [];
  let index = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    if (!line.trim()) {
      continue;
    }

    // Heading 1 or 2
    if (line.startsWith('# ') || line.startsWith('## ')) {
      const text = line.replace(/^#{1,2}\s+/, '');
      elements.push(
        <h2 key={index++} className="font-headline-sm text-lg font-bold text-[#1B1C1A] mt-3 mb-1">
          {renderFormattedText(text)}
        </h2>
      );
      continue;
    }

    // Heading 3
    if (line.startsWith('### ')) {
      const text = line.replace(/^###\s+/, '');
      elements.push(
        <div key={index++} className="flex items-center gap-2 text-[#884E00] mt-3.5 mb-1.5">
          <span className="material-symbols-outlined text-[20px]">air</span>
          <h3 className="font-label-lg text-sm font-bold text-[#884E00]">
            {renderFormattedText(text)}
          </h3>
        </div>
      );
      continue;
    }

    // Blockquote
    if (line.startsWith('> ')) {
      const quoteText = line.replace(/^>\s+/, '');
      const isTactileCue = quoteText.toLowerCase().includes('tactile cue');
      const isActionVerb = quoteText.toLowerCase().includes('action verb');

      elements.push(
        <div
          key={index++}
          className={`rounded-xl p-3 my-2.5 flex items-start gap-2.5 text-xs font-body-sm shadow-sm border ${
            isTactileCue
              ? 'bg-[#F4F4F0] border-[#E8E6DF] text-[#534437]'
              : isActionVerb
              ? 'bg-[#FFDCBF]/30 border-[#FFDCBF] text-[#884E00]'
              : 'bg-[#EFEEEA] border-[#E3E2DF] text-[#1B1C1A]'
          }`}
        >
          <span className="material-symbols-outlined text-[18px] text-[#305AB4] flex-shrink-0 mt-0.5">
            {isTactileCue ? 'lightbulb' : isActionVerb ? 'theater_comedy' : 'format_quote'}
          </span>
          <div className="leading-relaxed">
            {renderFormattedText(quoteText)}
          </div>
        </div>
      );
      continue;
    }

    // Bullet list item
    if (line.match(/^[-*]\s+/)) {
      const text = line.replace(/^[-*]\s+/, '');
      elements.push(
        <div key={index++} className="flex items-start gap-2 my-1.5 pl-1 text-sm text-[#1B1C1A]">
          <span className="w-1.5 h-1.5 rounded-full bg-[#884E00] mt-2 flex-shrink-0" />
          <div className="leading-relaxed">{renderFormattedText(text)}</div>
        </div>
      );
      continue;
    }

    // Numbered list item
    if (line.match(/^\d+\.\s+/)) {
      const match = line.match(/^(\d+)\.\s+(.*)/);
      if (match) {
        const num = match[1];
        const text = match[2];
        elements.push(
          <div key={index++} className="flex items-start gap-2.5 my-2 pl-0.5 text-sm text-[#1B1C1A]">
            <span className="font-label-sm text-xs font-bold text-[#884E00] bg-[#FFDCBF]/60 px-1.5 py-0.5 rounded flex-shrink-0 mt-0.5">
              {num}
            </span>
            <div className="leading-relaxed">{renderFormattedText(text)}</div>
          </div>
        );
        continue;
      }
    }

    // Normal paragraph
    elements.push(
      <p key={index++} className="text-sm font-body-md text-[#534437] my-2 leading-relaxed">
        {renderFormattedText(line)}
      </p>
    );
  }

  return <div className="space-y-1">{elements}</div>;
};
