import React, { useState, useEffect } from 'react';
import { startMetronome, stopMetronome, updateMetronomeBpm } from '../utils/audio';

interface Props {
  initialBpm?: number;
  label?: string;
}

export const InteractivePracticeBar: React.FC<Props> = ({
  initialBpm = 108,
  label = 'Rehearsal mm. 14–32 • Patter Lab',
}) => {
  const [bpm, setBpm] = useState(initialBpm);
  const [isPlaying, setIsPlaying] = useState(false);
  const [activeBeat, setActiveBeat] = useState(0);
  const [transposition, setTransposition] = useState<'baritone' | 'score' | 'tenor'>('score');

  const getTempoLabel = (val: number) => {
    if (val < 92) return 'Andante (Slow Drill)';
    if (val < 104) return 'Moderato';
    if (val < 116) return 'Allegro Moderato (Audition)';
    return 'Presto (Hyper Drill)';
  };

  const handleTogglePlay = () => {
    if (isPlaying) {
      stopMetronome();
      setIsPlaying(false);
    } else {
      startMetronome(bpm, (beat) => {
        setActiveBeat(beat);
      });
      setIsPlaying(true);
    }
  };

  const handleBpmChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = Number(e.target.value);
    setBpm(val);
    updateMetronomeBpm(val);
  };

  useEffect(() => {
    return () => {
      stopMetronome();
    };
  }, []);

  return (
    <div className="bg-[#FFFFFF] rounded-2xl p-4 shadow-md space-y-3.5 border border-[#E8E6DF]/80">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <span className="w-8 h-8 rounded-full bg-[#FFDCBF] flex items-center justify-center text-[#884E00]">
            <span className="material-symbols-outlined text-[18px]">tune</span>
          </span>
          <div>
            <h3 className="font-label-lg text-sm font-bold text-[#1B1C1A]">Interactive Practice Bar</h3>
            <span className="font-label-sm text-xs text-[#867465]">{label}</span>
          </div>
        </div>
        <button
          type="button"
          onClick={handleTogglePlay}
          className={`px-3 py-1.5 rounded-full text-white font-label-md text-xs font-semibold flex items-center gap-1.5 shadow-sm active:scale-95 transition-all cursor-pointer ${
            isPlaying ? 'bg-[#B51C12] hover:bg-[#930001]' : 'bg-[#884E00] hover:bg-[#6A3B00]'
          }`}
          title={isPlaying ? 'Stop metronome' : 'Start tempo drill'}
        >
          <span className="material-symbols-outlined text-[16px]">
            {isPlaying ? 'pause' : 'play_arrow'}
          </span>
          <span>{isPlaying ? 'Stop Metronome' : 'Audition Tempo'}</span>
        </button>
      </div>

      {/* Metronome Speed & Audio Wave Visualization */}
      <div className="bg-[#F4F4F0] rounded-xl p-3 space-y-2.5">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-1.5">
            <span className="material-symbols-outlined text-[18px] text-[#884E00]">speed</span>
            <span className="font-label-md text-xs text-[#1B1C1A] font-semibold">Target Metronome:</span>
            <span className="font-headline-sm text-base text-[#884E00] font-bold">{bpm}</span>
            <span className="font-label-sm text-xs text-[#867465]">BPM</span>
          </div>
          <span className="font-label-sm text-[11px] px-2 py-0.5 rounded-full bg-[#E9E8E4] text-[#534437] font-medium">
            {getTempoLabel(bpm)}
          </span>
        </div>

        {/* Tempo Slider */}
        <div className="flex items-center gap-2">
          <span className="font-label-sm text-xs text-[#867465]">80</span>
          <input
            type="range"
            min={80}
            max={132}
            value={bpm}
            onChange={handleBpmChange}
            className="w-full accent-[#884E00] h-1.5 bg-[#E3E2DF] rounded-lg cursor-pointer"
          />
          <span className="font-label-sm text-xs text-[#867465]">132</span>
        </div>

        {/* Waveform Animation Simulation with live beat tracking */}
        <div className="h-10 bg-[#E3E2DF] rounded-lg flex items-center justify-center gap-1 px-3 overflow-hidden select-none">
          {[
            { color: '#884E00', h: 'h-3', peak: 'h-6' },
            { color: '#884E00', h: 'h-6', peak: 'h-8' },
            { color: '#884E00', h: 'h-4', peak: 'h-7' },
            { color: '#305AB4', h: 'h-7', peak: 'h-9' },
            { color: '#305AB4', h: 'h-8', peak: 'h-10' },
            { color: '#884E00', h: 'h-5', peak: 'h-8' },
            { color: '#884E00', h: 'h-3', peak: 'h-6' },
            { color: '#305AB4', h: 'h-6', peak: 'h-9' },
            { color: '#884E00', h: 'h-8', peak: 'h-10' },
            { color: '#884E00', h: 'h-4', peak: 'h-7' },
            { color: '#305AB4', h: 'h-5', peak: 'h-8' },
            { color: '#884E00', h: 'h-3', peak: 'h-6' },
            { color: '#884E00', h: 'h-6', peak: 'h-9' },
          ].map((bar, idx) => {
            const isBeating = isPlaying && idx % 4 === activeBeat;
            return (
              <span
                key={idx}
                className={`w-1 rounded-full transition-all duration-150 ${
                  isBeating ? `${bar.peak} scale-y-125 opacity-100` : `${bar.h} opacity-75`
                }`}
                style={{
                  backgroundColor: bar.color,
                }}
              />
            );
          })}
        </div>
      </div>

      {/* Transposition Key Selector */}
      <div className="flex items-center justify-between pt-1">
        <span className="font-label-md text-xs text-[#534437] font-medium">Transposition Key:</span>
        <div className="flex items-center bg-[#EFEEEA] rounded-full p-1 gap-1">
          <button
            type="button"
            onClick={() => setTransposition('baritone')}
            className={`px-3 py-1 rounded-full text-xs transition-colors cursor-pointer ${
              transposition === 'baritone'
                ? 'bg-white text-[#884E00] font-bold shadow-sm'
                : 'text-[#534437] hover:text-[#1B1C1A]'
            }`}
          >
            -1 (Baritone)
          </button>
          <button
            type="button"
            onClick={() => setTransposition('score')}
            className={`px-3 py-1 rounded-full text-xs transition-colors cursor-pointer ${
              transposition === 'score'
                ? 'bg-white text-[#884E00] font-bold shadow-sm'
                : 'text-[#534437] hover:text-[#1B1C1A]'
            }`}
          >
            0 (Score Key)
          </button>
          <button
            type="button"
            onClick={() => setTransposition('tenor')}
            className={`px-3 py-1 rounded-full text-xs transition-colors cursor-pointer ${
              transposition === 'tenor'
                ? 'bg-white text-[#884E00] font-bold shadow-sm'
                : 'text-[#534437] hover:text-[#1B1C1A]'
            }`}
          >
            +1 (Tenor)
          </button>
        </div>
      </div>
    </div>
  );
};
