import React, { useState } from 'react';
import { useChat } from '../context/ChatContext';
import { DisciplineType } from '../types';

export const SideDrawer: React.FC = () => {
  const {
    isDrawerOpen,
    setIsDrawerOpen,
    conversations,
    currentConversationId,
    selectConversation,
    deleteConversation,
    clearAllConversations,
    setSelectedDiscipline,
    createNewConversation,
    setActiveTab,
  } = useChat();

  const [confirmClear, setConfirmClear] = useState(false);
  const [deleteConfirmId, setDeleteConfirmId] = useState<string | null>(null);

  const disciplines: { name: DisciplineType; icon: string; color: string }[] = [
    { name: 'Dance', icon: 'sports_gymnastics', color: 'text-[#884E00]' },
    { name: 'Singing', icon: 'mic', color: 'text-[#305AB4]' },
    { name: 'Music', icon: 'piano', color: 'text-[#884E00]' },
    { name: 'Theater', icon: 'masks', color: 'text-[#B51C12]' },
    { name: 'Acting', icon: 'movie', color: 'text-[#1B1C1A]' },
    { name: 'Choreography', icon: 'directions_run', color: 'text-[#884E00]' },
    { name: 'Stage Performance', icon: 'qr_code_2', color: 'text-[#305AB4]' },
  ];

  const handleDisciplineClick = (disc: DisciplineType) => {
    setSelectedDiscipline(disc);
    createNewConversation(disc);
    setIsDrawerOpen(false);
  };

  return (
    <>
      {/* Backdrop */}
      {isDrawerOpen && (
        <div
          className="fixed inset-0 bg-[#2F312E]/30 backdrop-blur-xs z-50 transition-opacity"
          onClick={() => setIsDrawerOpen(false)}
        />
      )}

      {/* Drawer */}
      <aside
        className={`fixed top-0 bottom-0 left-0 w-80 max-w-[85vw] bg-[#FAF9F5] z-50 shadow-[0_12px_36px_-6px_rgba(30,25,20,0.14)] flex flex-col transition-transform duration-300 ease-out border-r border-[#E8E6DF] ${
          isDrawerOpen ? 'translate-x-0' : '-translate-x-full'
        }`}
      >
        {/* Drawer Header */}
        <div className="h-16 px-4 flex items-center justify-between border-b border-[#E8E6DF]/60">
          <div className="flex items-center gap-2">
            <span className="material-symbols-outlined text-[#884E00] text-[24px]">
              theater_comedy
            </span>
            <span className="font-headline-sm text-base font-bold text-[#1B1C1A] tracking-tight">
              Grooveyy Studio
            </span>
          </div>
          <button
            type="button"
            aria-label="Close menu"
            onClick={() => setIsDrawerOpen(false)}
            className="w-10 h-10 rounded-full flex items-center justify-center text-[#534437] hover:text-[#1B1C1A] hover:bg-[#EFEEEA] transition-colors cursor-pointer"
          >
            <span className="material-symbols-outlined text-[22px]">close</span>
          </button>
        </div>

        {/* Drawer Content */}
        <div className="flex-1 overflow-y-auto px-3.5 py-4 space-y-6">
          {/* New Chat Button */}
          <button
            type="button"
            onClick={() => createNewConversation()}
            className="w-full flex items-center justify-center gap-2 px-4 py-2.5 rounded-xl bg-[#884E00] text-white hover:bg-[#6A3B00] transition-all font-label-md text-xs font-semibold shadow-xs active:scale-[0.98] cursor-pointer"
          >
            <span className="material-symbols-outlined text-[18px]">add</span>
            <span>New Rehearsal Session</span>
          </button>

          {/* Disciplines Section */}
          <div className="space-y-1">
            <p className="px-2 font-label-sm text-[11px] uppercase tracking-wider text-[#867465] font-semibold mb-1">
              Disciplines
            </p>
            {disciplines.map((d) => (
              <button
                key={d.name}
                type="button"
                onClick={() => handleDisciplineClick(d.name)}
                className="w-full flex items-center gap-2.5 px-3 py-2 rounded-xl hover:bg-[#EFEEEA] text-[#534437] hover:text-[#1B1C1A] transition-colors text-left cursor-pointer group"
              >
                <span className={`material-symbols-outlined text-[19px] ${d.color} group-hover:scale-110 transition-transform`}>
                  {d.icon}
                </span>
                <span className="font-label-lg text-xs font-medium flex-1">{d.name}</span>
                <span className="material-symbols-outlined text-[15px] text-[#867465] opacity-0 group-hover:opacity-100 transition-opacity">
                  add
                </span>
              </button>
            ))}
          </div>

          {/* Recent Rehearsals */}
          <div className="space-y-1">
            <div className="flex items-center justify-between px-2 mb-1">
              <p className="font-label-sm text-[11px] uppercase tracking-wider text-[#867465] font-semibold">
                Recent Rehearsals
              </p>
              {conversations.length > 1 && !confirmClear && (
                <button
                  type="button"
                  onClick={() => setConfirmClear(true)}
                  className="text-[10px] text-[#867465] hover:text-[#B51C12] transition-colors cursor-pointer"
                >
                  Clear All
                </button>
              )}
            </div>

            {confirmClear && (
              <div className="p-2.5 mb-2 bg-[#FFDAD6]/40 border border-[#FFDAD6] rounded-xl text-xs space-y-1.5">
                <p className="text-[#93000A] font-semibold">Clear all rehearsal history?</p>
                <div className="flex gap-2">
                  <button
                    type="button"
                    onClick={() => {
                      clearAllConversations();
                      setConfirmClear(false);
                    }}
                    className="px-2 py-1 bg-[#B51C12] text-white rounded text-[11px] font-semibold cursor-pointer"
                  >
                    Yes, Clear
                  </button>
                  <button
                    type="button"
                    onClick={() => setConfirmClear(false)}
                    className="px-2 py-1 bg-white border border-[#E3E2DF] text-[#1B1C1A] rounded text-[11px] cursor-pointer"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            )}

            <div className="space-y-1">
              {conversations.map((c) => {
                const isActive = c.id === currentConversationId;
                const isDeleting = deleteConfirmId === c.id;

                if (isDeleting) {
                  return (
                    <div
                      key={c.id}
                      className="p-2 bg-[#FFDAD6]/30 border border-[#FFDAD6] rounded-xl flex items-center justify-between text-xs"
                    >
                      <span className="text-[#93000A] truncate pr-1">Delete this session?</span>
                      <div className="flex items-center gap-1.5 flex-shrink-0">
                        <button
                          type="button"
                          onClick={() => {
                            deleteConversation(c.id);
                            setDeleteConfirmId(null);
                          }}
                          className="px-2 py-0.5 bg-[#B51C12] text-white rounded font-medium cursor-pointer"
                        >
                          Delete
                        </button>
                        <button
                          type="button"
                          onClick={() => setDeleteConfirmId(null)}
                          className="px-1.5 py-0.5 bg-white text-[#534437] rounded cursor-pointer"
                        >
                          Cancel
                        </button>
                      </div>
                    </div>
                  );
                }

                return (
                  <div
                    key={c.id}
                    className={`group flex items-center justify-between px-3 py-2 rounded-xl text-xs transition-colors cursor-pointer ${
                      isActive
                        ? 'bg-[#EFEEEA] text-[#1B1C1A] font-semibold shadow-xs'
                        : 'text-[#534437] hover:text-[#1B1C1A] hover:bg-[#F4F4F0]'
                    }`}
                  >
                    <button
                      type="button"
                      onClick={() => selectConversation(c.id)}
                      className="flex-1 text-left truncate pr-2 cursor-pointer"
                      title={c.title}
                    >
                      <span className="truncate block">{c.title}</span>
                    </button>
                    <button
                      type="button"
                      onClick={(e) => {
                        e.stopPropagation();
                        setDeleteConfirmId(c.id);
                      }}
                      className="opacity-0 group-hover:opacity-100 hover:text-[#B51C12] p-1 rounded transition-opacity cursor-pointer text-[#867465]"
                      title="Delete conversation"
                    >
                      <span className="material-symbols-outlined text-[16px]">delete</span>
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        </div>

        {/* Drawer Footer */}
        <div className="p-3 bg-[#F4F4F0] border-t border-[#E8E6DF] flex items-center justify-between">
          <button
            type="button"
            onClick={() => {
              setActiveTab('artist');
              setIsDrawerOpen(false);
            }}
            className="flex items-center gap-2 text-[#534437] hover:text-[#1B1C1A] transition-colors cursor-pointer text-xs font-medium"
          >
            <span className="material-symbols-outlined text-[20px]">settings</span>
            <span className="font-label-lg text-xs">Studio Settings</span>
          </button>
          <img
            src="/grooveyy-mascot.png"
            alt="Profile Avatar"
            className="w-8 h-8 rounded-full object-cover select-none border border-[#FFDCBF]"
          />
        </div>
      </aside>
    </>
  );
};
