import React, { useState } from 'react';
import { useChat } from '../context/ChatContext';

export const Header: React.FC = () => {
  const {
    activeTab,
    setActiveTab,
    isDrawerOpen,
    setIsDrawerOpen,
    createNewConversation,
    serverHealth,
    refreshHealth,
  } = useChat();

  const [showStatusPopover, setShowStatusPopover] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const getSubtitle = () => {
    switch (activeTab) {
      case 'coach':
      case 'studio':
        return 'Performing Arts Coach';
      case 'repertoire':
        return 'Repertoire Library';
      case 'artist':
        return 'Artist Profile';
      default:
        return 'Performing Arts Coach';
    }
  };

  const handleRefresh = async () => {
    setIsRefreshing(true);
    await refreshHealth(true);
    setTimeout(() => setIsRefreshing(false), 500);
  };

  // Status badge appearance based on truthful serverHealth
  const getStatusBadge = () => {
    switch (serverHealth.status) {
      case 'ready':
        return {
          dotClass: 'bg-emerald-500',
          badgeText: serverHealth.model || 'Gemini 3.8 Flash',
          label: 'Ready',
          borderClass: 'border-zinc-200 hover:border-zinc-300 bg-white text-zinc-700',
        };
      case 'connecting':
        return {
          dotClass: 'bg-amber-500 animate-pulse',
          badgeText: 'Connecting...',
          label: 'Connecting',
          borderClass: 'border-amber-200 bg-amber-50/70 text-amber-900',
        };
      case 'unavailable':
        return {
          dotClass: 'bg-amber-600',
          badgeText: 'High Demand (503)',
          label: 'Retrying',
          borderClass: 'border-amber-300 bg-amber-50 text-amber-950',
        };
      case 'configuration-error':
        return {
          dotClass: 'bg-rose-500',
          badgeText: 'Key Required',
          label: 'Setup Error',
          borderClass: 'border-rose-200 bg-rose-50 text-rose-900',
        };
    }
  };

  const statusInfo = getStatusBadge();

  return (
    <header className="fixed top-0 inset-x-0 z-40 bg-white/90 backdrop-blur-xl border-b border-zinc-200/80 shadow-[0_1px_6px_rgba(0,0,0,0.03)]">
      <div className="h-16 px-4 flex items-center justify-between max-w-4xl mx-auto">
        {/* Left: Menu Toggle + Brand */}
        <div className="flex items-center gap-2.5">
          <button
            type="button"
            aria-label="Open rehearsal drawer menu"
            onClick={() => setIsDrawerOpen(!isDrawerOpen)}
            className="w-10 h-10 rounded-xl flex items-center justify-center text-zinc-600 hover:text-zinc-950 hover:bg-zinc-100 transition-colors cursor-pointer"
          >
            <span className="material-symbols-outlined text-[22px]">menu</span>
          </button>
          <div
            className="flex flex-col cursor-pointer select-none group"
            onClick={() => setActiveTab('coach')}
          >
            <span className="text-[17px] font-bold tracking-tight text-zinc-900 group-hover:text-amber-700 transition-colors">
              Grooveyy
            </span>
            <span className="text-[11px] text-zinc-500 font-medium -mt-0.5">
              {getSubtitle()}
            </span>
          </div>
        </div>

        {/* Center/Right: Truthful Status Pill */}
        <div className="flex items-center gap-2 relative">
          <button
            type="button"
            onClick={() => setShowStatusPopover(!showStatusPopover)}
            className={`hidden sm:inline-flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-medium border shadow-xs transition-all cursor-pointer ${statusInfo.borderClass}`}
            title="Click for AI provider and model details"
          >
            <span className={`w-2 h-2 rounded-full ${statusInfo.dotClass}`} />
            <span className="font-medium truncate max-w-[140px]">{statusInfo.badgeText}</span>
            <span className="material-symbols-outlined text-[15px] text-zinc-400">
              expand_more
            </span>
          </button>

          {/* Status Details Modal / Dropdown */}
          {showStatusPopover && (
            <div className="absolute top-12 right-12 z-50 w-72 bg-white rounded-2xl shadow-xl border border-zinc-200 p-4 text-xs space-y-3 animate-fade-in">
              <div className="flex items-center justify-between border-b border-zinc-100 pb-2">
                <span className="font-semibold text-zinc-900 text-sm">AI Engine Status</span>
                <span
                  className={`px-2 py-0.5 rounded-full font-medium text-[11px] ${
                    serverHealth.status === 'ready'
                      ? 'bg-emerald-50 text-emerald-700'
                      : serverHealth.status === 'connecting'
                      ? 'bg-amber-50 text-amber-700'
                      : serverHealth.status === 'unavailable'
                      ? 'bg-orange-50 text-orange-700'
                      : 'bg-rose-50 text-rose-700'
                  }`}
                >
                  {statusInfo.label}
                </span>
              </div>

              <div className="space-y-2 text-zinc-600">
                <div className="flex justify-between">
                  <span className="text-zinc-500">Provider:</span>
                  <span className="font-medium text-zinc-800">{serverHealth.provider}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-zinc-500">Active Model:</span>
                  <span className="font-medium text-zinc-800 font-mono text-[11px]">
                    {serverHealth.model}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-zinc-500">Free Tier Limit:</span>
                  <span className="text-zinc-700 font-medium">15 RPM / 1M TPM</span>
                </div>
                {serverHealth.secondaryFallbackAvailable && (
                  <div className="flex justify-between">
                    <span className="text-zinc-500">Free Fallback:</span>
                    <span className="text-emerald-700 font-medium">Configured (Groq/OpenRouter)</span>
                  </div>
                )}
                <div className="pt-1 text-[11px] text-zinc-500 leading-relaxed border-t border-zinc-100">
                  {serverHealth.message}
                </div>
              </div>

              <div className="pt-2 flex justify-between items-center border-t border-zinc-100">
                <button
                  type="button"
                  onClick={handleRefresh}
                  disabled={isRefreshing}
                  className="px-3 py-1.5 rounded-lg bg-zinc-100 hover:bg-zinc-200 text-zinc-800 text-[11px] font-medium flex items-center gap-1.5 transition-colors cursor-pointer"
                >
                  <span
                    className={`material-symbols-outlined text-[14px] ${
                      isRefreshing ? 'animate-spin' : ''
                    }`}
                  >
                    refresh
                  </span>
                  Check Connection
                </button>
                <button
                  type="button"
                  onClick={() => setShowStatusPopover(false)}
                  className="text-zinc-400 hover:text-zinc-700 text-xs px-2 py-1"
                >
                  Close
                </button>
              </div>
            </div>
          )}

          {/* New Rehearsal Prompt */}
          <button
            type="button"
            aria-label="Start new rehearsal"
            onClick={() => createNewConversation()}
            className="w-9 h-9 rounded-xl flex items-center justify-center text-zinc-700 hover:text-zinc-950 hover:bg-zinc-100 border border-zinc-200/80 transition-all cursor-pointer shadow-xs active:scale-95"
            title="Start new rehearsal session"
          >
            <span className="material-symbols-outlined text-[19px]">add</span>
          </button>

          {/* Mascot Profile Button */}
          <button
            type="button"
            onClick={() => setActiveTab('artist')}
            className="w-9 h-9 rounded-full overflow-hidden p-0.5 bg-zinc-100 hover:ring-2 hover:ring-zinc-400 transition-all cursor-pointer shadow-xs"
            title="Artist Profile"
          >
            <img
              src="/grooveyy-mascot.png"
              alt="Grooveyy Mascot Profile"
              className="w-full h-full object-cover rounded-full select-none"
            />
          </button>
        </div>
      </div>
    </header>
  );
};
